--[[
  نسخة مفكوكة جزئياً + معدّلة
  - كل نصوص السكربت فُكّت من ترميز Base64 المخصص وأصبحت نصوصاً عادية
  - كل الثوابت الحسابية المموّهة تم تبسيطها لأرقام مباشرة
  - حلقة فك التشفير وحلقة خلط الجدول أُزيلتا (لم تعد لازمة)
  - مفاتيح التفعيل تُملأ تلقائياً => السكربت يشتغل عند أي لاعب
  - استدعاء Kick استُبدل بدالة غير مؤذية => لا يوجد طرد
]]

-- 1) تفعيل تلقائي لأي لاعب (بدل قائمة الأسماء)
do
  local env = (type(getgenv) == "function" and getgenv()) or _G or getfenv(0)
  local plr = nil
  pcall(function() plr = game:GetService("Players").LocalPlayer end)
  local who = (plr and plr.Name) or "Player"
  local keys = {
    "94eHERWQCEZ7I", "V96wFCJZywum", "6OUF7iwG8wEzw",
    "I8aYeKDnJeWw", "Nv0i8NnIwp4L",
  }
  for _, key in ipairs(keys) do
    if env[key] == nil or env[key] == false then env[key] = who end
    pcall(function() if _G[key] == nil or _G[key] == false then _G[key] = who end end)
  end
end

